  const heatCopy=definitions.find(row=>row[0]==='thousandFire')[3];heatCopy[0]+=' 主目标同样被点燃，每秒 6 伤害、持续 5 秒。';heatCopy[1]+=' 主目标同样被点燃，每秒 9 伤害、持续 5 秒。';
